{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.sku_live_mech_v2 as WITH data AS ( SELECT CASE WHEN UPPER(TRIM(sku)) like \'SN%\' or UPPER(TRIM(sku)) like \'BP%\' THEN UPPER(TRIM(sku)) ELSE sku_group END AS sku_group, from_party AS vendor_name, SUM( CASE WHEN transfer_branch_code != 32 THEN total_qty ELSE NULL END ) AS ordered, SUM( CASE WHEN transfer_branch_code = 8 THEN total_qty ELSE NULL END ) AS south, SUM( CASE WHEN transfer_branch_code = 94 THEN total_qty ELSE NULL END ) AS north FROM SNITCH_DB.MAPLEMONK.LOGIC_PURCHASE_ORDER GROUP BY 1, 2 ), puta AS ( SELECT CASE WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'SN%\' THEN UPPER(TRIM(\"Item Type skuCode\")) ELSE UPPER(TRIM(REGEXP_REPLACE(\"Item Type skuCode\"::STRING, \'-[^-]+$\', \'\'))) END AS sku_group, SUM( CASE WHEN \"Warehouse Name\" = \'SAPL-WH2\' THEN putaway_completed_quantity ELSE NULL END ) AS south, SUM( CASE WHEN \"Warehouse Name\" = \'SAPL-NORTH-TAURU\' THEN putaway_completed_quantity ELSE NULL END ) AS north, SUM( CASE WHEN \"Warehouse Name\" IN (\'SAPL-NORTH-TAURU\', \'SAPL-WH2\') THEN putaway_completed_quantity ELSE NULL END ) AS inwarded, MAX( CASE WHEN \"Warehouse Name\" = \'SAPL-WH2\' THEN putaway_updated::date ELSE NULL END ) AS south_inwarded_date, MAX( CASE WHEN \"Warehouse Name\" = \'SAPL-NORTH-TAURU\' THEN putaway_updated::date ELSE NULL END ) AS north_inwarded_date, MIN( CASE WHEN \"Warehouse Name\" IN (\'SAPL-NORTH-TAURU\', \'SAPL-WH2\') THEN putaway_updated::date ELSE NULL END ) AS inwarded_date FROM snitch_db.maplemonk.putaway_tracking WHERE final_type = \'New Inward\' GROUP BY 1 ), putaway_wh AS ( SELECT CASE WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'SN%\' THEN UPPER(TRIM(\"Item Type skuCode\")) ELSE UPPER(TRIM(REGEXP_REPLACE(\"Item Type skuCode\"::STRING, \'-[^-]+$\', \'\'))) END AS sku_group, MAX(CASE WHEN \"Warehouse Name\" = \'SAPL-WH2\' AND putaway_completed_quantity >= 10 THEN \'SAPL-WH2\' END) AS south_warehouse, MAX(CASE WHEN \"Warehouse Name\" = \'SAPL-NORTH-TAURU\' AND putaway_completed_quantity >= 10 THEN \'SAPL-NORTH-TAURU\' END) AS north_warehouse, MAX(CASE WHEN \"Warehouse Name\" = \'SAPL-WH2\' AND putaway_completed_quantity >= 10 THEN putaway_completed_date END) AS inward_date_south, MAX(CASE WHEN \"Warehouse Name\" = \'SAPL-NORTH-TAURU\' AND putaway_completed_quantity >= 10 THEN putaway_completed_date END) AS inward_date_north FROM snitch_db.maplemonk.putaway_tracking WHERE final_type = \'New Inward\' GROUP BY 1 ), final AS ( SELECT sku_group, d.ordered, d.vendor_name, d.south South_PO, d.north North_PO, p.inwarded, p.south south_inwarded, p.north North_inwarded, p.north_inwarded_date north_inwarded_date, p.south_inwarded_date south_inwarded_date, p.inwarded_date inwarded_date, b.final_live_date, (p.inwarded / NULLIF(d.ordered, 0)) inwarded_prec, ( CASE WHEN d.south > 0 THEN 1 ELSE 0 END ) + ( CASE WHEN d.north > 0 THEN 1 ELSE 0 END ) AS PO_raised_WH_count, ( CASE WHEN p.south > 0 THEN 1 ELSE 0 END ) + ( CASE WHEN p.north > 0 THEN 1 ELSE 0 END ) AS inwarded_WH_count, CASE WHEN c.sku_group IS NULL THEN \'No Offline Allocation\' ELSE \'Offline Allocated\' END Offline_Allocated_Status FROM data d LEFT JOIN puta p USING (sku_group) LEFT JOIN snitch_db.maplemonk.product_journey b USING (sku_group) LEFT JOIN ( SELECT DISTINCT CASE WHEN UPPER(TRIM(sku)) LIKE \'SN%\' THEN UPPER(TRIM(sku)) ELSE REGEXP_REPLACE(sku, \'-[^-]+$\', \'\') END AS sku_group FROM snitch_db.maplemonk.b2b_journey ) c USING (sku_group) WHERE ordered >= 100 ), live_check as ( select distinct sku_group, live_date from snitch_db.maplemonk.category_journey ), north_parsed AS ( SELECT t2.sku_no, t2.DELIVERY_STATUS_TYPE AS delivery_status_type, COALESCE( TRY_TO_DATE(t2.planned_date, \'DD/MM/YYYY\'), TRY_TO_DATE(t2.planned_date, \'DD-MM-YYYY\'), TRY_TO_DATE(t2.planned_date, \'DD-MON-YYYY\'), TRY_TO_DATE(t2.planned_date, \'DD MON YYYY\'), TRY_TO_DATE(t2.planned_date) ) AS planned_dt, COALESCE( TRY_TO_DATE(t2.actual_delivered_date, \'DD/MM/YYYY\'), TRY_TO_DATE(t2.actual_delivered_date, \'DD-MM-YYYY\'), TRY_TO_DATE(t2.actual_delivered_date, \'DD-MON-YYYY\'), TRY_TO_DATE(t2.actual_delivered_date, \'DD MON YYYY\'), TRY_TO_DATE(t2.actual_delivered_date) ) AS actual_dt FROM snitch_db.maplemonk.inward_details_sku_level t2 ), north_latest_planned AS ( SELECT sku_no, MAX(planned_dt) AS planned_dt_latest FROM north_parsed GROUP BY 1 ), north_actual_if_valid AS ( SELECT p.sku_no, MAX(p.actual_dt) AS actual_dt_selected FROM north_parsed p JOIN north_latest_planned lp ON lp.sku_no = p.sku_no WHERE p.actual_dt IS NOT NULL AND lp.planned_dt_latest IS NOT NULL AND p.actual_dt >= lp.planned_dt_latest GROUP BY 1 ), north_status AS ( SELECT p.sku_no, MAX(p.delivery_status_type) AS delivery_status_north FROM north_parsed p JOIN north_latest_planned lp ON lp.sku_no = p.sku_no AND p.planned_dt = lp.planned_dt_latest GROUP BY 1 ), north AS ( SELECT lp.sku_no, TO_CHAR(lp.planned_dt_latest, \'DD/MM/YYYY\') AS planned_date, TO_CHAR(a.actual_dt_selected, \'DD/MM/YYYY\') AS actual_delivered_date, ns.delivery_status_north FROM north_latest_planned lp LEFT JOIN north_actual_if_valid a ON a.sku_no = lp.sku_no LEFT JOIN north_status ns ON ns.sku_no = lp.sku_no ), south_parsed AS ( SELECT t3.sku_no, t3.DELIVERY_STATUS_TYPE AS delivery_status_type, COALESCE( TRY_TO_DATE(t3.planned_date, \'DD/MM/YYYY\'), TRY_TO_DATE(t3.planned_date, \'DD-MM-YYYY\'), TRY_TO_DATE(t3.planned_date, \'DD-MON-YYYY\'), TRY_TO_DATE(t3.planned_date, \'DD MON YYYY\'), TRY_TO_DATE(t3.planned_date) ) AS planned_dt, COALESCE( TRY_TO_DATE(t3.actual_delivered_date, \'DD/MM/YYYY\'), TRY_TO_DATE(t3.actual_delivered_date, \'DD-MM-YYYY\'), TRY_TO_DATE(t3.actual_delivered_date, \'DD-MON-YYYY\'), TRY_TO_DATE(t3.actual_delivered_date, \'DD MON YYYY\'), TRY_TO_DATE(t3.actual_delivered_date) ) AS actual_dt FROM snitch_db.maplemonk.SOUTH_INWARD_DETAILS_SKU_LEVEL t3 ), south_latest_planned AS ( SELECT sku_no, MAX(planned_dt) AS planned_dt_latest FROM south_parsed GROUP BY 1 ), south_actual_if_valid AS ( SELECT p.sku_no, MAX(p.actual_dt) AS actual_dt_selected FROM south_parsed p JOIN south_latest_planned lp ON lp.sku_no = p.sku_no WHERE p.actual_dt IS NOT NULL AND lp.planned_dt_latest IS NOT NULL AND p.actual_dt >= lp.planned_dt_latest GROUP BY 1 ), south_status AS ( SELECT p.sku_no, MAX(p.delivery_status_type) AS delivery_status_south FROM south_parsed p JOIN south_latest_planned lp ON lp.sku_no = p.sku_no AND p.planned_dt = lp.planned_dt_latest GROUP BY 1 ), south AS ( SELECT lp.sku_no, TO_CHAR(lp.planned_dt_latest, \'DD/MM/YYYY\') AS planned_date, TO_CHAR(a.actual_dt_selected, \'DD/MM/YYYY\') AS actual_delivered_date, ss.delivery_status_south FROM south_latest_planned lp LEFT JOIN south_actual_if_valid a ON a.sku_no = lp.sku_no LEFT JOIN south_status ss ON ss.sku_no = lp.sku_no ) SELECT distinct f.sku_group, f.ordered, f.vendor_name, CASE WHEN UPPER(TRIM(REGEXP_REPLACE(f.vendor_name, \'\\s*-\\s*[^-]+$\', \'\'))) IN ( \'INDIAN CONNECTION\', \'KARMA (GU)\', \'ACME INTERNATIONAL LTD\', \'INTENSE FOCUS ITECH PRIVATE LIMITED\', \'POOJA FASHION\', \'AROMA DE FRANCE\', \'GENTEX GLOBAL\', \'A ONE KNITWEARS\', \'STELLA INDUSSTRIES LIMITED\', \'MAXVALUE CREATIONS PRIVATE LIMITED\', \'DHRUV APPARELS\', \'SAMBHAV CAP CREATION\', \'ADITYA INTERNATIONAL\', \'ANKUSH KNITTING WORKS PRIVATE LIMITED\', \'EVELINE INTERNATIONAL\', \'GOOD GOOD WEARS\', \'MAITRI KNITWEAR\', \'MANGLAM COLORS PRIVATE LIMITED\', \'MINERVA FASHION PVT LTD\', \'NEW MIGLANI HOSIERY FACTORY\', \'OBERAI KNITWEAR\', \'SHIVAAY KNITWEAR\', \'SHREE KRISHNA ENTERPRISES\', \'ADEES EXPORTS\', \'ELYSIUM FOOTWEAR CONCEPT PVT LTD\', \'LEATHER LUXURY\', \'SP INTERNATIONAL\', \'DESHNOK INNOVATOR\', \'INDIA BRAIDS PVT LTD\', \'KRISHNA BEADS INDUSTRIES\', \'AMPH FASHION PVT. LTD\', \'SHREEJI GARMENTS MANUFACTURING PVT LTD\', \'ASM INDUSTRIES (INDIA) PVT. LTD.\', \'B D SILK INDUSTRIES PVT. LTD\', \'KARMA (MU)\', \'THIMBLERR COMMERCE AND TECHNOLOGY PVT LTD\', \'EURO SUITS MANUFACTURING CO PRIVATE LIMITED\' ) THEN \'north\' WHEN UPPER(TRIM(REGEXP_REPLACE(f.vendor_name, \'\\s*-\\s*[^-]+$\', \'\'))) IN ( \'TEXPORT INDUSTRIES PVT LTD\', \'ANUVARTHH APPARELS PVT.LTD.\', \'BLUE MONKEY CLOTHING COMPANY\', \'G G GARMENTS\', \'K P GARMENT HOUSE\', \'KHARVA APPARELS\', \'LEANDRO FASHION\', \'LOHITH CREATIONS\', \'MARQUEE INDUSTRIES PVT LTD\', \'MAX KNITS INC\', \'MSQ CLOTHING LLP\', \'NALANDA DESIGNERS\', \'OM SHIVA SHAKTHI ENTERPRISES\', \'SAI TEXTILES\', \'SRI SAI TEJA CREATION\', \'V D DECORS\', \'VASUKI CREATIONS\', \'VIGNESH APPEARLS\', \'VIGNESH CREATIONS\', \'VIJAY RAM CREATIONS\', \'AMITHRAJ APPARELS\', \'KNOSKIN FASHIONS PVT. LTD\', \'VR CREATIONS\', \'ABHAY APPARELS\', \'AXCELLER\', \'DIVINITEE GENESIS APPAREL PVT LTD\', \'G T EXPORTS\', \'GO GO INTERNATIONAL PRIVATE LTD\', \'HEVIN CLOTHING\', \'KHATUSHREE INDIA\', \'KP PRODUCTION HOUSE LLP\', \'M SQUARE\', \'PRESTEIGE APPAREL PVT LTD\', \'S R APPARELS\', \'SAI TEXTILES SHADEZ\', \'THIMBLERR COMMERCE AND TECHNOLOGY PVT LTD\', \'TRIO APPARELS INDIA PVT. LTD\', \'V D FASHIONS\', \'NAVKAR AGENCY\', \'PRANAV INTERNATIONAL KNITWEAR\', \'THANDEESHWARA FASHIONS\', \'ORCHID CLOTH COMPANY\', \'HANUMAN TEXTILES\', \'ADDON CLOTHING\', \'CHECK MATE\', \'CHILLCARE APPARELS PRIVATE LIMITED\', \'ETTRO\', \'GROOVY FASHIONS\', \'LAMSOLEE CLOTHING COMPANY\', \'RAUNAK TEXTILES\', \'RENAISSANCE FASHIONS\', \'SAANVI TRADERS\', \'VISHNU TRADING CO.\', \'VISTA GLOBAL COMPANY\', \'CUT AND SEW EXPORTS\', \'VEEYA FASHION\', \'PADMA SHRI KNIT WEAR\', \'VP KNIT FASHIONS\', \'INDIANA PUNTOS CLOTHING\', \'A N ASSOCIATES\', \'ASIAN CLOTHINGS\', \'VANITHA GARMENTS\', \'WEAREVER\', \'CORE INDIA\', \'GO GO INTERNATIONAL PRIVATE LIMITED\', \'MOTIF CLOTHING CO.\', \'V.D.FASHIONS\', \'WALT ENTERPRISES\', \'VINTAGE\', \'THANDEESWARA FASHIONS\', \'SMART CLOTHING\' ) THEN \'south\' ELSE NULL END AS vendor_region, f.South_PO, f.North_PO, f.inwarded, f.south_inwarded, f.North_inwarded, f.PO_raised_WH_count, f.inwarded_WH_count, ROUND(100 * f.inwarded_prec, 1) AS inwarded_prec, CASE WHEN f.inwarded_prec >= 0.75 THEN f.inwarded_date END AS WH_Live_date, cj.image_url AS SKU_image, CASE WHEN f.sku_group LIKE \'MP%\' THEN \'Marketplace Specific SKU\' WHEN f.inwarded_prec >= 0.75 THEN \'Ready to go live\' WHEN INWARDED_WH_COUNT = 2 THEN \'Ready to go live\' WHEN f.PO_raised_WH_count < f.inwarded_WH_count THEN \'Ready to go live\' ELSE \'Not Ready to go Live\' END AS Remarks, f.Offline_Allocated_Status, CASE WHEN f.sku_group NOT LIKE \'MP%\' THEN CASE WHEN f.inwarded_prec >= 0.75 AND f.final_live_date IS NULL THEN \'Make it Live in Online\' WHEN f.inwarded_prec < 0.75 and (f.PO_Raised_WH_COUNT > INWARDED_WH_COUNT or INWARDED_WH_COUNT <= 1 ) AND f.final_live_date IS NOT NULL THEN \'Should not have made Live\' WHEN f.inwarded_prec >= 0.75 AND f.final_live_date IS NOT NULL THEN \'Already Live in Online\' WHEN f.inwarded_prec < 0.75 and (f.PO_Raised_WH_COUNT <= INWARDED_WH_COUNT ) AND f.final_live_date IS NOT NULL THEN \'Already Live in Online\' WHEN INWARDED_WH_COUNT = 2 AND f.final_live_date IS NULL THEN \'Make it Live in Online\' WHEN f.PO_Raised_WH_COUNT < INWARDED_WH_COUNT AND f.final_live_date IS NULL THEN \'Make it Live in Online\' ELSE \'Do not Make Live\' END END AS Online_Remarks, CASE WHEN f.sku_group NOT LIKE \'MP%\' THEN CASE WHEN f.inwarded_prec >= 0.75 AND f.Offline_Allocated_Status = \'No Offline Allocation\' THEN \'Make Allocation in Offline\' WHEN f.inwarded_prec < 0.75 AND f.Offline_Allocated_Status = \'Offline Allocated\' THEN \'Should not have made Allocations\' WHEN f.inwarded_prec >= 0.75 AND f.Offline_Allocated_Status = \'Offline Allocated\' THEN \'Offline Allocation Already Done\' ELSE \'Do not Make Allocations\' END END AS Offline_Remarks, lf.live_date, CASE WHEN REGEXP_LIKE(north.planned_date, \'^[0-9]{2}-[A-Za-z]{3}-[0-9]{4}$\') THEN TO_CHAR(TO_DATE(north.planned_date, \'DD-MON-YYYY\'), \'DD/MM/YYYY\') ELSE north.planned_date END AS north_planned_date, north.actual_delivered_date AS north_actual_delivered_date, south.planned_date AS south_planned_date, CASE WHEN REGEXP_LIKE(south.actual_delivered_date,\'^[0-9]{1,2}-[A-Za-z]{3}-[0-9]{4}$\') THEN TO_CHAR(TO_DATE(south.actual_delivered_date,\'DD-MON-YYYY\'),\'DD/MM/YYYY\') WHEN REGEXP_LIKE(south.actual_delivered_date,\'^[0-9]{1,2} [A-Za-z]{3} [0-9]{4}$\') THEN TO_CHAR(TO_DATE(south.actual_delivered_date,\'DD MON YYYY\'),\'DD/MM/YYYY\') WHEN REGEXP_LIKE(south.actual_delivered_date,\'^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$\') THEN TO_CHAR(TO_DATE(south.actual_delivered_date,\'DD/MM/YYYY\'),\'DD/MM/YYYY\') ELSE NULL END AS south_actual_delivered_date, pw.south_warehouse, pw.north_warehouse, CASE WHEN pw.inward_date_north IS NOT NULL AND TRY_TO_DATE(north_actual_delivered_date, \'DD/MM/YYYY\') IS NOT NULL AND TRY_TO_DATE(north_actual_delivered_date, \'DD/MM/YYYY\') > pw.inward_date_north THEN NULL ELSE pw.inward_date_north END AS inward_date_north, CASE WHEN pw.inward_date_south IS NOT NULL AND TRY_TO_DATE(south_actual_delivered_date, \'DD/MM/YYYY\') IS NOT NULL AND TRY_TO_DATE(south_actual_delivered_date, \'DD/MM/YYYY\') > pw.inward_date_south THEN NULL ELSE pw.inward_date_south END AS inward_date_south, DATEDIFF( \'DAY\', TRY_TO_DATE(north_planned_date, \'DD/MM/YYYY\'), TRY_TO_DATE(north_actual_delivered_date, \'DD/MM/YYYY\') ) AS DIFF_NORTH_RECIEVED, DATEDIFF( \'DAY\', TRY_TO_DATE(south_planned_date, \'DD/MM/YYYY\'), TRY_TO_DATE(south_actual_delivered_date, \'DD/MM/YYYY\') ) AS DIFF_SOUTH_RECIEVED, north.delivery_status_north AS DELIVERY_STATUS_NORTH, south.delivery_status_south AS DELIVERY_STATUS_SOUTH FROM final f LEFT JOIN north ON north.sku_no = sku_group LEFT JOIN south ON south.sku_no = sku_group LEFT JOIN putaway_wh pw ON pw.sku_group = f.sku_group LEFT JOIN snitch_db.maplemonk.category_journey cj ON cj.sku_group = f.sku_group left join live_check lf on f.sku_group = lf.sku_group WHERE ((lf.live_date > \'2026-01-01\' or lf.live_date is null) ) AND UPPER(TRIM(f.sku_group)) NOT in ( \'PJ07\', \'PJ05\', \'SB4\', \'PP BINS\', \'NSB2\', \'MPB4\', \'MPB7\', \'CBB001\', \'CBS001\', \'89092763660\', \'89092763661\', \'89092763681\') AND UPPER(TRIM(f.sku_group)) NOT iLIKE \'NT00%\';",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
